const seedCities = async () => {
  try {
    await mongoose.connect(process.env.MONGO_URI_MAIN);

    console.log("DB Connected");

    // 🔥 clear old
    await City.deleteMany();

    // 🔥 insert new
    await City.insertMany(cities, { ordered: false });

    console.log("Cities Seeded ✅");

    process.exit();

  } catch (err) {
    console.log(err);
    process.exit(1);
  }
};

seedCities();